    in_block = False
    count = 0
    for line in lines:
        stripped = line.strip()
        if '/-' in stripped and '-/' not in stripped:
            in_block = True
        if '-/' in stripped:
            in_block = False
            continue
        if in_block or stripped.startswith('--'):
            continue
        if ' sorry' in line or stripped == 'sorry':
            count += 1
    status = "PASS" if count == 0 else "FAIL"
    print(f"  {filepath:45s} | sorry: {count} | {status}")

