def test_kaprekar():
    """Test on 4-digit Kaprekar routine."""
    print("\n=== KAPREKAR 4-DIGIT ===")
    T = {}
    for x in range(10000):
        s = f"{x:04d}"
        desc = int(''.join(sorted(s, reverse=True)))
