def test_random_systems():
    """Test on random systems of various sizes."""
    print("\n=== RANDOM SYSTEMS ===")
    random.seed(42)
    all_pass = True

    for n in [10, 50, 100, 500, 1000, 5000, 10000]:
        mapping = [random.randint(0, n - 1) for _ in range(n)]
