depth2 = {}
for n in range(100):
    seen = {}
    x = n
    step = 0
    while x not in seen:
        seen[x] = step
        x = T2[x]
        step += 1
    depth2[n] = seen[x]

labels2 = [depth2[n] for n in range(100)]
while True:
    sig = {}
    for n in range(100):
        sig[n] = (labels2[n], labels2[T2[n]])
    unique = {}
    new_labels = []
    for n in range(100):
        s = sig[n]
        if s not in unique:
            unique[s] = len(unique)
        new_labels.append(unique[s])
    if new_labels == labels2:
        break
    labels2 = new_labels

print(f"2-digit exact quotient: {max(labels2)+1} classes")

