val_to_idx = {v: i for i, v in enumerate(kap_values)}

# Quotient dynamics: T_Q[i] = where value i goes next
T_Q = np.zeros(M, dtype=int)
for i, v in enumerate(kap_values):
    T_Q[i] = val_to_idx[T[v]]

# Koopman operators
K_full = np.zeros((N, N))
for i in range(N):
    K_full[T[i], i] = 1.0

