diff = Phi @ K_full - K_Q @ Phi
max_err = np.max(np.abs(diff))
fro_err = np.linalg.norm(diff, 'fro')

# Adjoint: K_full^T @ Phi^T - Phi^T @ K_Q^T
diff_adj = K_full.T @ Phi.T - Phi.T @ K_Q.T
max_err_adj = np.max(np.abs(diff_adj))

