# ============================================================

# The 55 Kaprekar values have GCD = 9
# The Smith invariants d1|d2|d3 must divide the lattice generated by these values
gcd_55 = 0
for v in kap_values:
    gcd_55 = np.gcd(gcd_55, v)
print(f"\nGCD of 55 Kaprekar values: {gcd_55}")

# d1 = 9 = base - 1
d1 = 9
