# Build quotient graph from exact quotient (8 classes)
def exact_quotient(T, labels):
    labels = list(labels)
    N = len(T)
    while True:
        sig = {}
        for n in range(N):
            tn = T[n]
            sig[n] = (labels[n], labels[tn] if tn < N else -1)
        unique = {}
        new = []
        for n in range(N):
            s = sig[n]
            if s not in unique:
                unique[s] = len(unique)
            new.append(unique[s])
        if new == labels:
            break
        labels = new
    classes = defaultdict(list)
    for n in range(N):
        classes[labels[n]].append(n)
    return labels, classes

ex_labels, ex_classes = exact_quotient(T, [depth[n] for n in range(10000)])
n_classes = len(ex_classes)

# Graph Laplacian
adj = defaultdict(set)
for n in range(10000):
    src = ex_labels[n]
    dst = ex_labels[T[n]] if T[n] < 10000 else src
    adj[src].add(dst)
    adj[dst].add(src)

L = np.zeros((n_classes, n_classes))
for i in range(n_classes):
    neighbors = adj[i]
    L[i, i] = len(neighbors)
    for j in neighbors:
        L[i, j] = -1

eigvals_L, eigvecs_L = la.eigh(L)

