# Recompute quickly
def bipartite_rank(T, blocks):
    m = len(blocks)
    label = {}
    for i, b in enumerate(blocks):
        for x in b:
            label[x] = i
    parent = list(range(2*m))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[ry] = rx
    for i, blk in enumerate(blocks):
        for x in blk:
            if x in label:
                tx = T[x]
                if tx in label:
                    j = label[tx]
                    union(i, j+m)
    roots = {find(i) for i in range(2*m)}
    return m - len(roots)

# Quadratic map defect ranks (from earlier data)
